import ast
import operator

def evaluate(node, user):
    if isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.Name):
        if node.id == 'id':
            return user['id']
        elif node.id == 'name':
            return user['name']
        elif node.id == 'email':
            return user['email']
        else:
            raise ValueError(f"Unknown variable: {node.id}")
    elif isinstance(node, ast.Compare):
        left = evaluate(node.left, user)
        # Assuming single comparison for now, or handle chain
        # The prompt says 'id > 1 and email != x@y.org'
        # node.ops is list of ops, node.comparators is list of comparators
        # Example: name == 'Ada' -> node.ops=[Eq()], node.comparators=[Constant(value='Ada')]

        # This is a simplification. Let's see how ast.parse works
        op = node.ops[0]
        right = evaluate(node.comparators[0], user)

        if isinstance(op, ast.Eq): return left == right
        if isinstance(op, ast.NotEq): return left != right
        if isinstance(op, ast.Lt): return left < right
        if isinstance(op, ast.LtE): return left <= right
        if isinstance(op, ast.Gt): return left > right
        if isinstance(op, ast.GtE): return left >= right
        raise ValueError(f"Unknown op: {type(op)}")
    elif isinstance(node, ast.BoolOp):
        values = [evaluate(v, user) for v in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
    elif isinstance(node, ast.UnaryOp):
        if isinstance(node.op, ast.Not):
            return not evaluate(node.operand, user)

    raise ValueError(f"Unsupported node: {type(node)}")

def filter_users(expression, users):
    try:
        tree = ast.parse(expression, mode='eval')
    except SyntaxError:
        return None

    # We need to validate the tree
    # No function calls, no attribute access
    for node in ast.walk(tree.body):
        if isinstance(node, (ast.Call, ast.Attribute)):
            return None
        # Allow only the allowed nodes
        if not isinstance(node, (ast.Expression, ast.Compare, ast.BoolOp, ast.UnaryOp, 
                                 ast.Constant, ast.Name, ast.Eq, ast.NotEq, ast.Lt, 
                                 ast.LtE, ast.Gt, ast.GtE, ast.And, ast.Or, ast.Not)):
             # Actually, ast.Name, ast.Constant, etc are allowed.
             # Wait, ast.walk will go through all nodes, including the top one.
             pass

    # Actually, ast.walk includes the node itself.
    # The check should be on every node

    valid_nodes = (
        ast.Expression, ast.Compare, ast.BoolOp, ast.UnaryOp,
        ast.Constant, ast.Name,
        ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE,
        ast.And, ast.Or, ast.Not,
        ast.Load
    )

    for node in ast.walk(tree.body):
        if not isinstance(node, valid_nodes):
            return None

    # Also check if Name.id is valid
    for node in ast.walk(tree.body):
        if isinstance(node, ast.Name):
            if node.id not in ['id', 'name', 'email']:
                return None

    result = []
    for user in users:
        try:
            if evaluate(tree.body, user):
                result.append(user)
        except:
            pass # Maybe skip or handle
    return result

